import sys, random
sys.path.insert(0,'.')
from modules.byte_program import *
random.seed(3)
for k in range(0,70):
    m=random.randrange(1,2**64)
    assert geo(k,m)==sum(pow(m,i,2**64) for i in range(k))%(2**64)
for n in range(0,70):
    assert pow257(n)==pow(257,n,2**64), n
print('geo/pow ok')
random.seed(7)
def build(depth):
    if depth==0 or random.random()<0.3:
        return literal(bytes(random.randrange(1,255) for _ in range(random.randrange(0,12))))
    k=random.randrange(3)
    if k==0: return concat(build(depth-1),build(depth-1))
    if k==1: return repeat(build(depth-1), random.randrange(0,4))
    n=build(depth-1)
    if n.length==0: return n
    lo=random.randrange(0,n.length); hi=random.randrange(lo,n.length)
    return cut(n,lo,hi)
bad=0; checked=0
for trial in range(4000):
    n=build(4)
    data=read(n,0,n.length)
    assert len(data)==n.length
    for _ in range(6):
        if n.length==0: continue
        lo=random.randrange(0,n.length); hi=random.randrange(lo,n.length)
        seg=data[lo:hi]; m=len(seg)
        ref=sum((x+1)*257**(m-1-i) for i,x in enumerate(seg))%(2**64)
        checked+=1
        if hash_range(n,lo,hi)!=ref:
            bad+=1; print('MISMATCH',trial,lo,hi,n.length); break
        if read(n,lo,hi)!=seg:
            bad+=1; print('READ MISMATCH',trial); break
print('checked',checked,'bad',bad)
"
